import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_K": 32},
        ),
    ],
    key=["D"],
)
@triton.jit
def _triplet_margin_loss_kernel(
    anchor_ptr,
    positive_ptr,
    negative_ptr,
    loss_ptr,
    B,
    D,
    stride_ab,
    stride_ad,
    stride_pb,
    stride_pd,
    stride_nb,
    stride_nd,
    margin,
    eps,
    BLOCK_K: tl.constexpr,
):
    row = tl.program_id(0)
    if row >= B:
        return

    base_a = row.to(tl.int64) * stride_ab
    base_p = row.to(tl.int64) * stride_pb
    base_n = row.to(tl.int64) * stride_nb

    sum_pos_sq = 0.0
    sum_neg_sq = 0.0

    for k_start in range(0, D, BLOCK_K):
        offs_k = k_start + tl.arange(0, BLOCK_K)
        mask_k = offs_k < D

        a = tl.load(
            anchor_ptr + base_a + offs_k * stride_ad, mask=mask_k, other=0.0
        ).to(tl.float32)
        p = tl.load(
            positive_ptr + base_p + offs_k * stride_pd, mask=mask_k, other=0.0
        ).to(tl.float32)
        n = tl.load(
            negative_ptr + base_n + offs_k * stride_nd, mask=mask_k, other=0.0
        ).to(tl.float32)

        diff_pos = a - p + eps
        diff_neg = a - n + eps
        sum_pos_sq += tl.sum(diff_pos * diff_pos, axis=0)
        sum_neg_sq += tl.sum(diff_neg * diff_neg, axis=0)

    d_pos = tl.sqrt(sum_pos_sq)
    d_neg = tl.sqrt(sum_neg_sq)

    loss_val = tl.maximum(d_pos - d_neg + margin, 0.0)

    tl.atomic_add(loss_ptr, loss_val, sem="relaxed")


class Model(nn.Module):
    def __init__(self, margin=1.0):
        super(Model, self).__init__()
        self.margin = margin
        self.eps = 1e-6

    def forward(self, anchor, positive, negative):
        device = anchor.device
        B, D = anchor.shape

        anchor = anchor.contiguous()
        positive = positive.contiguous()
        negative = negative.contiguous()

        loss_accum = torch.zeros((), device=device, dtype=torch.float32)

        grid = (B,)
        _triplet_margin_loss_kernel[grid](
            anchor,
            positive,
            negative,
            loss_accum,
            B,
            D,
            anchor.stride(0),
            anchor.stride(1),
            positive.stride(0),
            positive.stride(1),
            negative.stride(0),
            negative.stride(1),
            self.margin,
            self.eps,
        )

        return loss_accum / B


